export function ThemeWatcher() {
  const [dark, setDark] = useState(false);
  useEffect(() => {
    const media = matchMedia('(prefers-color-scheme: dark)');
    const update = () => setDark(media.matches);
    media.addEventListener('change', update);
    return () => media.removeEventListener('change', update);
  }, []);
  return <Filter enabled={dark} />;
}

pub async fn with_backoff<F, T>(mut send: F) -> Result<T, Error>
where F: FnMut() -> Result<T, Error> {
    for attempt in 0..3 {
        match send() {
            Ok(value) => return Ok(value),
            Err(Error::Transient(_)) => tokio::time::sleep(Duration::from_millis(1 << attempt)).await,
            Err(error) => return Err(error),
        }
    }
    Err(Error::Exhausted)
}

func Retry(ctx context.Context, send func(context.Context) error) error {
    for attempt := 0; attempt < 3; attempt++ {
        if err := send(ctx); err == nil { return nil }
        select {
        case <-time.After(time.Second << attempt):
        case <-ctx.Done(): return ctx.Err()
        }
    }
    return errors.New("exhausted")
}

